259	float PhysicsHelper::pointToSegmentDistance(const Vec2& point, const Vec2& segA, const Vec2& segB)
260	{
261	    const Vec2 ab = segB - segA;
262	    const float lengthSq = ab.getLengthSq();
263	
264	    if (lengthSq < kHelperEpsilon)
265	        return (point - segA).getLength();
266	
267	    const float t = clampf((point - segA).dot(ab) / lengthSq, 0.0f, 1.0f);
268	
269	    return (point - (segA + ab * t)).getLength();
270	}
271	
272	float PhysicsHelper::polygonArea(const Vec2* verts, int count)
273	{
274	    if (verts == nullptr || count < 3)
275	        return 0.0f;
276	
277	    float sum = 0.0f;
278	    for (int i = 0; i < count; ++i)
279	    {
280	        sum += verts[i].cross(verts[(i + 1) % count]);
281	    }
282	
283	    return std::fabs(sum) * 0.5f;
284	}
