286	float PhysicsHelper::polygonMoment(float mass, const Vec2* verts, int count, const Vec2& offset)
287	{
288	    if (verts == nullptr || count < 3)
289	        return 0.0f;
290	
291	    std::vector<cpVect> cpvs(count);
292	    points2cpvs(verts, cpvs.data(), count);
293	
294	    return cpfloat2float(cpMomentForPoly(mass, count, cpvs.data(), point2cpv(offset), 0.0f));
295	}
