#include "physics/CCPhysicsWorldQuery.h"
#if CC_USE_PHYSICS

#include <algorithm>
#include <cmath>
#include <vector>

#include "chipmunk/chipmunk_private.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    const unsigned int kAllCategories = 0xFFFFFFFFu;

    // Finite stand-in for "as far as the world goes". Chipmunk needs a real number for the
    // nearest-point queries, and an infinite one would poison the returned distance, so the
    // horizon is set well beyond the extents of a normal cocos2d-x scene instead.
    const float kQueryHorizon = 100000.0f;

    // Hits this close to a segment end are treated as touching the endpoint, not as crossing it.
    const float kAlphaEpsilon = 1e-4f;

    // Path clearance is sampled along each leg; the step keeps short legs cheap and the cap
    // keeps a very long leg from turning into an unbounded number of queries.
    const float kClearanceSampleStep = 16.0f;
    const int kMaxClearanceSamples = 64;

    // Upper bound on the samples taken per axis by findOpenPositions.
    const int kMaxGridSamplesPerAxis = 256;

    // A mask of 0 or 0xFFFFFFFF means "every category". Any other mask is passed as both the
    // categories and the acceptance mask, so a shape matches when it shares a bit with it.
    cpShapeFilter makeCategoryFilter(unsigned int categoryMask)
    {
        if (categoryMask == 0u || categoryMask == kAllCategories)
        {
            return CP_SHAPE_FILTER_ALL;
        }

        return cpShapeFilterNew(CP_NO_GROUP,
                                static_cast<cpBitmask>(categoryMask),
                                static_cast<cpBitmask>(categoryMask));
    }

    PhysicsShape* toPhysicsShape(const cpShape* shape)
    {
        if (shape == nullptr)
        {
            return nullptr;
        }

        return static_cast<PhysicsShape*>(cpShapeGetUserData(const_cast<cpShape*>(shape)));
    }

    PhysicsBody* toPhysicsBody(const cpShape* shape)
    {
        PhysicsShape* physicsShape = toPhysicsShape(shape);
        return physicsShape == nullptr ? nullptr : physicsShape->getBody();
    }

    template <typename T>
    void appendUnique(std::vector<T>& container, T value)
    {
        if (std::find(container.begin(), container.end(), value) == container.end())
        {
            container.push_back(value);
        }
    }

    // Distance from a point to the closest matching surface, or -1 when nothing is within
    // maxDistance. A point inside a shape reports 0 so that a negative value never means "inside".
    float nearestSurfaceDistance(cpSpace* space, cpVect point, cpShapeFilter filter, float maxDistance)
    {
        if (space == nullptr)
        {
            return -1.0f;
        }

        cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
        if (cpSpacePointQueryNearest(space, point, maxDistance, filter, &info) == nullptr)
        {
            return -1.0f;
        }

        return info.distance > 0.0 ? PhysicsHelper::cpfloat2float(info.distance) : 0.0f;
    }

    int clearanceSampleCount(float length)
    {
        if (length <= 0.0f)
        {
            return 2;
        }

        int count = static_cast<int>(length / kClearanceSampleStep) + 2;
        return count > kMaxClearanceSamples ? kMaxClearanceSamples : count;
    }

    void collectSegmentHit(cpShape* shape, cpVect point, cpVect normal, cpFloat alpha, void* data)
    {
        std::vector<PhysicsSegmentQueryResult>* results = static_cast<std::vector<PhysicsSegmentQueryResult>*>(data);
        PhysicsShape* physicsShape = toPhysicsShape(shape);

        if (results == nullptr || physicsShape == nullptr)
        {
            return;
        }

        PhysicsSegmentQueryResult hit;
        hit.shape = physicsShape;
        hit.point = PhysicsHelper::cpv2point(point);
        hit.normal = PhysicsHelper::cpv2point(normal);
        hit.alpha = PhysicsHelper::cpfloat2float(alpha);

        results->push_back(hit);
    }

    void collectPointHit(cpShape* shape, cpVect point, cpFloat distance, cpVect gradient, void* data)
    {
        std::vector<PhysicsNearestResult>* results = static_cast<std::vector<PhysicsNearestResult>*>(data);
        PhysicsShape* physicsShape = toPhysicsShape(shape);

        if (results == nullptr || physicsShape == nullptr)
        {
            return;
        }

        PhysicsNearestResult hit;
        hit.shape = physicsShape;
        hit.point = PhysicsHelper::cpv2point(point);
        hit.distance = PhysicsHelper::cpfloat2float(distance);
        hit.gradient = PhysicsHelper::cpv2point(gradient);

        results->push_back(hit);
    }

    void collectShape(cpShape* shape, void* data)
    {
        std::vector<PhysicsShape*>* results = static_cast<std::vector<PhysicsShape*>*>(data);
        PhysicsShape* physicsShape = toPhysicsShape(shape);

        if (results == nullptr || physicsShape == nullptr)
        {
            return;
        }

        // One PhysicsShape can own several cpShapes, so the same owner may be reported twice.
        appendUnique(*results, physicsShape);
    }

    void collectBody(cpShape* shape, void* data)
    {
        std::vector<PhysicsBody*>* results = static_cast<std::vector<PhysicsBody*>*>(data);
        PhysicsBody* body = toPhysicsBody(shape);

        if (results == nullptr || body == nullptr)
        {
            return;
        }

        appendUnique(*results, body);
    }

    struct BodyDistance
    {
        PhysicsBody* body;
        float distance;
    };

    struct CircleCollector
    {
        cpVect center;
        cpFloat radius;
        std::vector<BodyDistance> bodies;
    };

    void collectCircleShape(cpShape* shape, void* data)
    {
        CircleCollector* collector = static_cast<CircleCollector*>(data);
        PhysicsBody* body = toPhysicsBody(shape);

        if (collector == nullptr || body == nullptr)
        {
            return;
        }

        // The bounding box test is only a broad phase; measure the real surface distance here.
        cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
        cpShapePointQuery(shape, collector->center, &info);

        if (info.distance > collector->radius)
        {
            return;
        }

        const float distance = info.distance > 0.0 ? PhysicsHelper::cpfloat2float(info.distance) : 0.0f;

        for (auto& entry : collector->bodies)
        {
            if (entry.body == body)
            {
                if (distance < entry.distance)
                {
                    entry.distance = distance;
                }
                return;
            }
        }

        BodyDistance entry = { body, distance };
        collector->bodies.push_back(entry);
    }

    struct ContactCollector
    {
        std::vector<cpArbiter*> visited;
        std::vector<PhysicsContactPairInfo> pairs;
    };

    void collectArbiter(cpBody* /*body*/, cpArbiter* arbiter, void* data)
    {
        ContactCollector* collector = static_cast<ContactCollector*>(data);

        if (collector == nullptr || arbiter == nullptr)
        {
            return;
        }

        // Both bodies of a colliding pair list the same arbiter, so it is recorded only once.
        if (std::find(collector->visited.begin(), collector->visited.end(), arbiter) != collector->visited.end())
        {
            return;
        }
        collector->visited.push_back(arbiter);

        cpShape* cpShapeA = nullptr;
        cpShape* cpShapeB = nullptr;
        cpArbiterGetShapes(arbiter, &cpShapeA, &cpShapeB);

        PhysicsBody* bodyA = toPhysicsBody(cpShapeA);
        PhysicsBody* bodyB = toPhysicsBody(cpShapeB);

        if (bodyA == nullptr || bodyB == nullptr)
        {
            return;
        }

        PhysicsContactPairInfo info;
        info.bodyA = bodyA;
        info.bodyB = bodyB;
        info.contactPoint = Vec2::ZERO;
        info.contactNormal = PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter));
        info.penetration = 0.0f;

        const int count = cpArbiterGetCount(arbiter);
        if (count > 0)
        {
            Vec2 sum = Vec2::ZERO;
            for (int i = 0; i < count; ++i)
            {
                const Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, i));
                const Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(arbiter, i));
                sum += (pointA + pointB) * 0.5f;

                // Chipmunk reports overlap as a negative distance, so take the magnitude.
                const float depth = std::fabs(PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, i)));
                if (depth > info.penetration)
                {
                    info.penetration = depth;
                }
            }

            info.contactPoint = sum / static_cast<float>(count);
        }

        collector->pairs.push_back(info);
    }

    void collectBodyArbiters(cpBody* body, void* data)
    {
        if (body == nullptr)
        {
            return;
        }

        cpBodyEachArbiter(body, collectArbiter, data);
    }
}

PhysicsWorldQuery::PhysicsWorldQuery()
: _space(nullptr)
, _initialized(false)
{
}

PhysicsWorldQuery::~PhysicsWorldQuery()
{
}

bool PhysicsWorldQuery::init(cpSpace* space)
{
    CCASSERT(space != nullptr, "the space can not be nullptr");

    if (space == nullptr)
    {
        return false;
    }

    _space = space;
    _initialized = true;

    return true;
}

PhysicsNearestResult PhysicsWorldQuery::queryNearestPoint(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    // A null shape paired with distance -1 is the "nothing found" answer. A real hit can also
    // report a negative distance: that means the query point lies inside the shape.
    PhysicsNearestResult result = { nullptr, Vec2::ZERO, -1.0f, Vec2::ZERO };

    if (!_initialized || _space == nullptr)
    {
        return result;
    }

    cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              maxDistance,
                                              makeCategoryFilter(categoryMask),
                                              &info);

    PhysicsShape* physicsShape = toPhysicsShape(shape);
    if (physicsShape == nullptr)
    {
        return result;
    }

    result.shape = physicsShape;
    result.point = PhysicsHelper::cpv2point(info.point);
    result.distance = PhysicsHelper::cpfloat2float(info.distance);
    result.gradient = PhysicsHelper::cpv2point(info.gradient);

    return result;
}

std::vector<PhysicsSegmentQueryResult> PhysicsWorldQuery::querySegment(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsSegmentQueryResult> results;

    if (!_initialized || _space == nullptr)
    {
        return results;
    }

    cpSpaceSegmentQuery(_space,
                        PhysicsHelper::point2cpv(start),
                        PhysicsHelper::point2cpv(end),
                        radius < 0.0f ? 0.0f : radius,
                        makeCategoryFilter(categoryMask),
                        collectSegmentHit,
                        &results);

    // Near hits first; a stable sort leaves equal alphas in the order they were collected.
    std::stable_sort(results.begin(), results.end(),
                     [](const PhysicsSegmentQueryResult& a, const PhysicsSegmentQueryResult& b) {
                         return a.alpha < b.alpha;
                     });

    return results;
}

PhysicsSegmentQueryResult PhysicsWorldQuery::querySegmentFirst(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    // Miss reads as "the ray survived the whole segment": alpha 1, no shape, point at the end.
    PhysicsSegmentQueryResult result = { nullptr, end, Vec2::ZERO, 1.0f };

    if (!_initialized || _space == nullptr)
    {
        return result;
    }

    cpSegmentQueryInfo info = { nullptr, PhysicsHelper::point2cpv(end), cpvzero, 1.0 };
    cpShape* shape = cpSpaceSegmentQueryFirst(_space,
                                              PhysicsHelper::point2cpv(start),
                                              PhysicsHelper::point2cpv(end),
                                              radius < 0.0f ? 0.0f : radius,
                                              makeCategoryFilter(categoryMask),
                                              &info);

    PhysicsShape* physicsShape = toPhysicsShape(shape);
    if (physicsShape == nullptr)
    {
        return result;
    }

    result.shape = physicsShape;
    result.point = PhysicsHelper::cpv2point(info.point);
    result.normal = PhysicsHelper::cpv2point(info.normal);
    result.alpha = PhysicsHelper::cpfloat2float(info.alpha);

    return result;
}

std::vector<PhysicsBBQueryResult> PhysicsWorldQuery::queryBoundingBox(const Rect& rect, unsigned int categoryMask)
{
    std::vector<PhysicsBBQueryResult> results;

    if (!_initialized || _space == nullptr)
    {
        return results;
    }

    std::vector<PhysicsShape*> shapes;
    cpSpaceBBQuery(_space,
                   PhysicsHelper::rect2cpbb(rect),
                   makeCategoryFilter(categoryMask),
                   collectShape,
                   &shapes);

    results.reserve(shapes.size());
    for (auto shape : shapes)
    {
        PhysicsBBQueryResult entry = { shape };
        results.push_back(entry);
    }

    return results;
}

std::vector<PhysicsNearestResult> PhysicsWorldQuery::queryPointAll(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    std::vector<PhysicsNearestResult> results;

    if (!_initialized || _space == nullptr)
    {
        return results;
    }

    cpSpacePointQuery(_space,
                      PhysicsHelper::point2cpv(point),
                      maxDistance,
                      makeCategoryFilter(categoryMask),
                      collectPointHit,
                      &results);

    // Closest first; a stable sort leaves equal distances in the order they were collected.
    std::stable_sort(results.begin(), results.end(),
                     [](const PhysicsNearestResult& a, const PhysicsNearestResult& b) {
                         return a.distance < b.distance;
                     });

    return results;
}

int PhysicsWorldQuery::countBodiesInRect(const Rect& rect, unsigned int categoryMask)
{
    if (!_initialized || _space == nullptr)
    {
        return 0;
    }

    // Counts owners, not shapes: a body with several shapes inside the rect counts once.
    std::vector<PhysicsBody*> bodies;
    cpSpaceBBQuery(_space,
                   PhysicsHelper::rect2cpbb(rect),
                   makeCategoryFilter(categoryMask),
                   collectBody,
                   &bodies);

    return static_cast<int>(bodies.size());
}

bool PhysicsWorldQuery::isPointOccupied(const Vec2& point, unsigned int categoryMask)
{
    // An uninitialised facade knows of no shapes, so it cannot affirm occupancy.
    if (!_initialized || _space == nullptr)
    {
        return false;
    }

    // Max distance 0 keeps this to the shapes the point is actually inside of.
    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              0.0f,
                                              makeCategoryFilter(categoryMask),
                                              nullptr);

    return shape != nullptr;
}

float PhysicsWorldQuery::distanceToNearestBody(const Vec2& point, unsigned int categoryMask)
{
    if (!_initialized || _space == nullptr)
    {
        return -1.0f;
    }

    return nearestSurfaceDistance(_space,
                                  PhysicsHelper::point2cpv(point),
                                  makeCategoryFilter(categoryMask),
                                  kQueryHorizon);
}

std::vector<PhysicsContactPairInfo> PhysicsWorldQuery::getActiveContacts()
{
    if (!_initialized || _space == nullptr)
    {
        return {};
    }

    ContactCollector collector;
    cpSpaceEachBody(_space, collectBodyArbiters, &collector);

    return collector.pairs;
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesAlongRay(const Vec2& start, const Vec2& end, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;

    // The hits arrive sorted by alpha, so first occurrence order is distance order.
    std::vector<PhysicsSegmentQueryResult> hits = querySegment(start, end, 0.0f, categoryMask);
    bodies.reserve(hits.size());

    for (const auto& hit : hits)
    {
        PhysicsBody* body = hit.shape == nullptr ? nullptr : hit.shape->getBody();
        if (body != nullptr)
        {
            appendUnique(bodies, body);
        }
    }

    return bodies;
}

PhysicsBody* PhysicsWorldQuery::getBodyAtPoint(const Vec2& point)
{
    if (!_initialized || _space == nullptr)
    {
        return nullptr;
    }

    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              0.0f,
                                              CP_SHAPE_FILTER_ALL,
                                              nullptr);

    return toPhysicsBody(shape);
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesInCircle(const Vec2& center, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;

    if (!_initialized || _space == nullptr || radius < 0.0f)
    {
        return bodies;
    }

    CircleCollector collector;
    collector.center = PhysicsHelper::point2cpv(center);
    collector.radius = radius;

    cpSpaceBBQuery(_space,
                   cpBBNewForExtents(collector.center, radius, radius),
                   makeCategoryFilter(categoryMask),
                   collectCircleShape,
                   &collector);

    // Closest first; a stable sort leaves equal distances in collection order.
    std::stable_sort(collector.bodies.begin(), collector.bodies.end(),
                     [](const BodyDistance& a, const BodyDistance& b) {
                         return a.distance < b.distance;
                     });

    bodies.reserve(collector.bodies.size());
    for (const auto& entry : collector.bodies)
    {
        bodies.push_back(entry.body);
    }

    return bodies;
}

bool PhysicsWorldQuery::lineOfSight(const Vec2& start, const Vec2& end, unsigned int blockMask)
{
    // An uninitialised facade cannot see anything, so it cannot affirm a clear line either.
    if (!_initialized || _space == nullptr)
    {
        return false;
    }

    if (start == end)
    {
        return true;
    }

    // Only a shape strictly between the endpoints blocks: a shape touching start or end
    // (the observer's own body, or the target itself) leaves the sight line intact.
    std::vector<PhysicsSegmentQueryResult> hits = querySegment(start, end, 0.0f, blockMask);
    for (const auto& hit : hits)
    {
        if (hit.alpha > kAlphaEpsilon && hit.alpha < 1.0f - kAlphaEpsilon)
        {
            return false;
        }
    }

    return true;
}

float PhysicsWorldQuery::computePathClearance(const Vec2* path, int pathCount, unsigned int blockMask)
{
    // A degenerate path has no legs to measure; -1 is the sentinel for "no clearance computed".
    if (path == nullptr || pathCount < 2 || !_initialized || _space == nullptr)
    {
        return -1.0f;
    }

    const cpShapeFilter filter = makeCategoryFilter(blockMask);

    // Nothing blocking within the horizon reports the horizon itself as the clearance.
    float clearance = kQueryHorizon;

    for (int i = 0; i + 1 < pathCount; ++i)
    {
        const Vec2& from = path[i];
        const Vec2& to = path[i + 1];
        const cpVect cpFrom = PhysicsHelper::point2cpv(from);
        const cpVect cpTo = PhysicsHelper::point2cpv(to);

        // A leg that a blocking shape crosses has no clearance at all, and no later leg can
        // push the minimum below zero, so the answer is settled.
        if (cpSpaceSegmentQueryFirst(_space, cpFrom, cpTo, 0.0f, filter, nullptr) != nullptr)
        {
            return 0.0f;
        }

        const int samples = clearanceSampleCount(from.distance(to));
        for (int s = 0; s < samples; ++s)
        {
            const float t = static_cast<float>(s) / static_cast<float>(samples - 1);
            const Vec2 sample = from + (to - from) * t;
            const float distance = nearestSurfaceDistance(_space, PhysicsHelper::point2cpv(sample), filter, kQueryHorizon);

            if (distance >= 0.0f && distance < clearance)
            {
                clearance = distance;
            }
        }
    }

    return clearance;
}

std::vector<Vec2> PhysicsWorldQuery::findOpenPositions(const Rect& searchArea, float spacing, float clearance, unsigned int blockMask)
{
    std::vector<Vec2> positions;

    if (!_initialized || _space == nullptr || spacing <= 0.0f)
    {
        return positions;
    }

    int columns = static_cast<int>(std::floor(searchArea.size.width / spacing)) + 1;
    int rows = static_cast<int>(std::floor(searchArea.size.height / spacing)) + 1;

    if (columns <= 0 || rows <= 0)
    {
        return positions;
    }

    columns = std::min(columns, kMaxGridSamplesPerAxis);
    rows = std::min(rows, kMaxGridSamplesPerAxis);

    const cpShapeFilter filter = makeCategoryFilter(blockMask);
    const float reach = clearance > 0.0f ? clearance : 0.0f;
    const float originX = searchArea.getMinX();
    const float originY = searchArea.getMinY();

    // Row major: bottom row first, left to right within each row.
    for (int row = 0; row < rows; ++row)
    {
        const float y = originY + spacing * static_cast<float>(row);

        for (int column = 0; column < columns; ++column)
        {
            const float x = originX + spacing * static_cast<float>(column);

            // No blocking shape within reach means the sample is farther than the clearance.
            if (cpSpacePointQueryNearest(_space, cpv(x, y), reach, filter, nullptr) == nullptr)
            {
                positions.push_back(Vec2(x, y));
            }
        }
    }

    return positions;
}

